package dev.zomboid.remains.expand;
import net.minecraft.world.inventory.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.ItemStack;
public final class ExpandedBodies {
 static Object call(Object o,String n,Object...a){return FastReflection.call(o,n,a);}static Object get(Object o,String n){return FastReflection.get(o,n);}
 public static void install(Object corpse,Object data){FastReflection.set(corpse,"inventory",new ExpandedStorage(get(corpse,"inventory"),data));}
 public static void restore(Object corpse,Object tag){ExpandedStorage storage=(ExpandedStorage)get(corpse,"inventory");int size=((Number)call(tag,"getInt","ZGCapacity")).intValue();Object list=call(tag,"getList","Items",10);int length=((Number)call(list,"size")).intValue();for(int i=0;i<length;i++){int slot=((Number)call(call(list,"getCompound",i),"getInt","Slot")).intValue();if(slot>=0&&slot<Integer.MAX_VALUE-9)size=Math.max(size,slot+1);}storage.ensure(Math.max(storage.getContainerSize(),size));}
 public static void saveSize(Object corpse,Object tag){call(tag,"putInt","ZGCapacity",((ExpandedStorage)get(corpse,"inventory")).getContainerSize());}
 public static Object menu(Object corpse,Object data,Object pos,Object level,int id,Object inventory,Object player){ExpandedStorage storage=(ExpandedStorage)get(corpse,"inventory");if(storage.getContainerSize()<=54){int rows=Math.max(1,storage.getContainerSize()/9);@SuppressWarnings("unchecked") MenuType<ChestMenu> type=(MenuType<ChestMenu>)get(MenuType.class,"GENERIC_9x"+rows);return new ChestMenu(type,id,(Inventory)inventory,storage,rows){@Override public boolean stillValid(Player p){return valid(corpse,data,pos,level,p);}};}return new PagedMenu(id,(Inventory)inventory,storage,corpse,data,pos,level);}
 static boolean valid(Object corpse,Object data,Object pos,Object level,Object player){if(Boolean.TRUE.equals(get(corpse,"skeleton")))return false;Object map=get(data,"corpses"),key=call(pos,"asLong");if(call(map,"get",key)!=corpse)return false;Object owner=FastReflection.type("dev.zomboid.remains.ZombieRemainsLoot");if(!call(owner,"blockId",call(level,"getBlockState",pos)).equals(get(corpse,"block")))return false;return ((Number)call(player,"distanceToSqr",((Number)call(pos,"getX")).doubleValue()+.5,((Number)call(pos,"getY")).doubleValue()+.5,((Number)call(pos,"getZ")).doubleValue()+.5)).doubleValue()<=64;}
 static ItemStack icon(String item,String text){Object base=get(FastReflection.type("net.minecraft.world.item.Items"),item);ItemStack s=(ItemStack)FastReflection.make("net.minecraft.world.item.ItemStack",base);Object key=get(FastReflection.type("net.minecraft.core.component.DataComponents"),"CUSTOM_NAME");Object name=call(FastReflection.type("net.minecraft.network.chat.Component"),"literal",text);call(s,"set",key,name);return s;}
}
